import { renderToString } from 'react-dom/server';
import { App } from '/home/sandbox/workspace/src/App';

function run(stored: string | null) {
  const data = new Map<string, string>();
  if (stored !== null) data.set('theme', stored);
  (globalThis as any).window = {
    localStorage: { getItem: (k: string) => data.get(k) ?? null, setItem: (k: string, v: string) => data.set(k, v) },
    matchMedia: () => ({ matches: false, addEventListener() {}, removeEventListener() {} }),
  };
  const html = renderToString(<App />);
  const checked = [...html.matchAll(/<input[^>]*value="([^"]+)"[^>]*checked=""/g)].map((m) => m[1]);
  const current = html.match(/Текущая тема: (?:<!-- -->)?([a-z-]+)/)?.[1];
  console.log(JSON.stringify({ stored, checkedOption: checked, currentTheme: current }));
}
run(null);
run('dark');
run('system');
run('garbage');
